cdk_nag_finding: {'rule_id': 'AwsSolutions-L1', 'resource_id': 'ASHCDKNagScanner/deployment--chat-endpoint.yaml/ChatLambda', 'compliance': 'Non-Compliant', 'exception_reason': 'N/A', 'rule_level': 'Error', 'rule_info': 'The non-container Lambda function is not configured to use the latest runtime version.'}
cfn_resource: {'Resources': {'ChatLambda': {'Type': 'AWS::Lambda::Function', 'Properties': {'FunctionName': 'RestaurantAgent-Chat', 'Runtime': 'python3.13', 'Handler': 'index.handler', 'Role': {'Fn::GetAtt': ['ChatLambdaRole', 'Arn']}, 'Timeout': 300, 'MemorySize': 512, 'ReservedConcurrentExecutions': 10, 'KmsKeyArn': {'Fn::GetAtt': ['ChatLambdaEnvEncryptionKey', 'Arn']}, 'DeadLetterConfig': {'TargetArn': {'Fn::GetAtt': ['ChatLambdaDLQ', 'Arn']}}, 'Environment': {'Variables': {'AGENT_RUNTIME_ARN': {'Ref': 'AgentRuntimeArn'}}}, 'Code': {'ZipFile': 'import json
import boto3
import os

def handler(event, context):
    try:
        body = json.loads(event.get('body', '{}'))
        prompt = body.get('prompt', '')
        session_id = body.get('sessionId', f"session-{context.aws_request_id}")

        if not prompt:
            return {
                'statusCode': 400,
                'headers': cors_headers(),
                'body': json.dumps({'error': 'prompt required'})
            }

        # Invoke AgentCore
        client = boto3.client('bedrock-agentcore')
        agent_arn = os.environ['AGENT_RUNTIME_ARN']

        response = client.invoke_agent_runtime(
            agentRuntimeArn=agent_arn,
            payload=json.dumps({
                'prompt': prompt,
                'sessionId': session_id
            }).encode('utf-8')
        )

        # Read response
        response_body = response['response'].read().decode('utf-8')
        result = json.loads(response_body)

        return {
            'statusCode': 200,
            'headers': cors_headers(),
            'body': json.dumps({
                'result': result.get('result', ''),
                'sessionId': session_id
            })
        }
    except Exception as e:
        print(f"Error: {str(e)}")
        return {
            'statusCode': 500,
            'headers': cors_headers(),
            'body': json.dumps({'error': str(e)})
        }

def cors_headers():
    return {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Content-Type',
        'Access-Control-Allow-Methods': 'POST,OPTIONS'
    }
'}}}}}
